import Selectors from 'local_greetings/local/greetings/selectors';
import * as Str from 'core/str';

export const init = () => {
    window.console.log("hello ajit");
    var x = Selectors;
    window.console.log(x,Str);

    registerEventListeners();

};

const registerEventListeners = () => {
    document.addEventListener('click', e=> {
        if (e.target.closest(Selectors.actions.showGreetingButtonAjit)) {
            const greetingBlock = document.querySelector(Selectors.regions.greetingBlockAjit);

            if (greetingBlock) {
                const nameField = document.querySelector(Selectors.regions.inputFieldAjit);
                const msg = document.createElement("h2");

                 userGreeting(nameField.value)
                .then((greetingStr) => {
                    msg.append(greetingStr);
                    greetingBlock.append(msg);
                    return;
                })
                .catch(e);
            }
        }

        if (e.target.closest(Selectors.actions.resetButtonAjit)) {
            const nameField = document.querySelector(Selectors.regions.inputFieldAjit);
            nameField.value = '';
            const greetingBlock = document.querySelector(Selectors.regions.greetingBlockAjit);
            greetingBlock.innerHTML = '';
        }
    });

};


/**
 * Return a personalised greeting.
 *
 * @param   {String} name The name of the person to greet
 * @returns {Promise}
 */
const userGreeting = (name) => Str.getString('greetinguserau', 'local_greetings', name);